-- Públicos explícitos e correspondência editorial; sem inferir autorização por similaridade.
alter table public.orientacoes_empresariais add column if not exists publico text not null default 'empresa'
 check (publico in ('empresa','cac','militar','policial','todos'));
create or replace function public.chave_pergunta_pce(q text)
returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select trim(regexp_replace(regexp_replace(lower(translate(left(coalesce(q,''),2000),
 'áàâãäéèêëíìîïóòôõöúùûüç','aaaaaeeeeiiiiooooouuuuc')),'[?!.,;:]',' ','g'),'[[:space:]]+',' ','g'));
$$;
create or replace function public.fontes_dispositivos_pce(refs text[],p_data date)
returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object(
 'trecho_id',d.id,'norma_id',n.id,'titulo',n.titulo,'dispositivo',d.referencia,
 'conteudo',d.texto_literal,'pagina',d.pagina,'relevancia',0,'status',n.status,
 'ultima_verificacao',n.ultima_verificacao,'dispositivo_id',d.id,'texto_literal',d.texto_literal,
 'status_dispositivo',d.status,'literal_conferido',d.conferido,
 'vigencia_inicio',d.vigencia_inicio,'vigencia_fim',d.vigencia_fim,
 'fonte_oficial',n.fonte_oficial,'nome_arquivo',doc.nome_arquivo,'sha256',doc.sha256,
 'tipo_conteudo','fundamento_orientacao','relacoes','[]'::jsonb,
 'conferencia_textual',d.metadata->'conferencia_textual'
 ) order by array_position(refs,d.id::text)),'[]'::jsonb)
 from dispositivos d join normas n on n.id=d.norma_id
 left join documentos doc on doc.id=d.documento_id
 where d.id::text=any(refs) and d.conferido and d.status in ('vigente','alterado')
 and n.usar_como_fundamento and n.status in ('vigente','vigente_com_alteracoes','parcialmente_vigente')
 and (d.vigencia_inicio is null or d.vigencia_inicio<=p_data)
 and (d.vigencia_fim is null or d.vigencia_fim>=p_data)
 and (n.vigencia_inicio is null or n.vigencia_inicio<=p_data)
 and (n.vigencia_fim is null or n.vigencia_fim>=p_data);
$$;
-- Citações resolvidas por título e referência, sem IDs gerados fixos.
do $seed$
declare g jsonb; refs jsonb; alvo uuid;
begin
 for g in select value from jsonb_array_elements($dados$[{"pergunta_modelo":"O que é PCE?","titulo":"Conceito de PCE","publico":"todos","produto":"todos","atividade":"todos","texto":"PCE significa Produto Controlado pelo Exército. O enquadramento decorre de poder destrutivo, potencial de dano, restrição por segurança pública ou interesse militar. Para um produto concreto, confira sua nomenclatura e especificações na lista de PCE.","referencias":[{"norma":"Decreto nº 10.030, de 30 de setembro de 2019","referencia":"Anexo I, art. 2º, caput e incisos I e II"},{"norma":"Portaria nº 118 COLOG, de 4 de outubro de 2019","referencia":"Art. 1º"}],"fontes_complementares":[]},{"pergunta_modelo":"Quantas armas um atirador nível 3 pode ter?","titulo":"Armas do atirador nível 3","publico":"cac","produto":"armas","atividade":"aquisicao","texto":"O limite geral de aquisição do nível 3 é de 16 armas, com até 4 restritas, observadas as autorizações e condições. Alto rendimento tem regime próprio. Quantidade superior de armas permitidas exige necessidade comprovada e autorização motivada; não é automática.","referencias":[{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 36, incisos I a III"},{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 37, §§ 1º a 5º"},{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Arts. 38-B a 38-E"}],"fontes_complementares":[]},{"pergunta_modelo":"Quais os limites de munição para CAC?","titulo":"Munição por modalidade e nível","publico":"cac","produto":"municoes","atividade":"aquisicao","texto":"CAC não tem limite único. Para tiro desportivo em 12 meses: nível 1, 4.000 cartuchos por atirador e 8.000 por arma .22 LR/SHORT; nível 2, 10.000 e 16.000; nível 3, 20.000 e 32.000, respectivamente. Observe vinculação ao acervo e condições de uso restrito. Caça excepcional: até 500 por ano, por arma. Alto rendimento tem regime próprio. Informe modalidade, nível e calibre para aplicar ao caso.","referencias":[{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 37, incisos I a III"},{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 37, §§ 1º a 5º"},{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 39, caput, incisos I a III e parágrafo único"},{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Arts. 38-B a 38-E"}],"fontes_complementares":[]},{"pergunta_modelo":"Como funciona a Guia de Tráfego para CAC?","titulo":"Guia de Tráfego para CAC","publico":"cac","produto":"armas","atividade":"transporte","texto":"A guia autoriza transporte desmuniciado, com munição em recipiente próprio, dentro da finalidade, trajeto e validade. Não concede porte de defesa pessoal. Atualmente, solicite pelo serviço da PF no Sinarm-CAC, com os documentos da finalidade, e aguarde o deferimento. Leia referências antigas ao SisGCorp junto do procedimento atual da PF.","referencias":[{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 33, caput e §§ 1º a 3º"}],"fontes_complementares":[{"titulo":"PF — Guia de Tráfego para CAC","url":"https://www.gov.br/pt-br/servicos/obter-guia-de-trafego-para-cacador-excepcional-atirador-desportivo-e-colecionador","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"Militar do Exército pode portar arma de fogo?","titulo":"Porte por categoria militar","publico":"militar","produto":"armas","atividade":"todos","texto":"Depende da categoria. Oficiais, subtenentes e sargentos de carreira têm regimes próprios; oficiais temporários estão limitados à convocação. Sargentos temporários, cabos, taifeiros e soldados dependem de concessão excepcional. Confira restrições e comprovação documental; ser militar isoladamente não comprova porte em qualquer situação.","referencias":[{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 7º e parágrafo único"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 8º e parágrafo único"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 9º, caput e §§ 1º a 3º"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 10, caput e incisos I e II"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 13, incisos I a V"}],"fontes_complementares":[]},{"pergunta_modelo":"Soldado do Exército pode ter porte de arma?","titulo":"Porte de arma particular por soldado","publico":"militar","produto":"armas","atividade":"todos","texto":"Soldado não tem porte automático de arma particular. A concessão é excepcional, mediante fatos e circunstâncias que a justifiquem. Durante o Serviço Militar Inicial há vedação. Não confunda armamento de serviço e porte particular.","referencias":[{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 10, caput e incisos I e II"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 13, incisos I a V"}],"fontes_complementares":[]},{"pergunta_modelo":"Soldado temporário tem porte automático?","titulo":"Porte de arma particular por soldado","publico":"militar","produto":"armas","atividade":"todos","texto":"Soldado não tem porte automático de arma particular. A concessão é excepcional, mediante fatos e circunstâncias que a justifiquem. Durante o Serviço Militar Inicial há vedação. Não confunda armamento de serviço e porte particular.","referencias":[{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 10, caput e incisos I e II"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 13, incisos I a V"}],"fontes_complementares":[]},{"pergunta_modelo":"Militar sem porte pode transportar arma?","titulo":"Transporte por militar sem porte","publico":"militar","produto":"armas","atividade":"transporte","texto":"Pode transportar sua arma com a respectiva GT, desmuniciada, observadas as condições e o limite de aquisição de munições. A guia não substitui autorização de porte.","referencias":[{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 29 e §§ 1º e 2º"}],"fontes_complementares":[]},{"pergunta_modelo":"Policial militar pode adquirir arma de uso restrito?","titulo":"Arma restrita por policial militar","publico":"policial","produto":"armas","atividade":"aquisicao","texto":"Sim, mediante requisitos e autorização competente. A redação cadastrada admite até 4 armas, com até 2 restritas; em serviço ativo, dentro desse limite, até 1 portátil longa restrita. A autorização de aquisição de restrita compete ao Exército. Aquisição, registro e porte são distintos.","referencias":[{"norma":"Portaria nº 167 COLOG/C Ex, de 22 de janeiro de 2024","referencia":"Normas, art. 2º, caput e incisos I a III"},{"norma":"Portaria nº 167 COLOG/C Ex, de 22 de janeiro de 2024","referencia":"Normas, art. 2º, § 1º, incisos I e II"}],"fontes_complementares":[]},{"pergunta_modelo":"Quais documentos um policial militar precisa para adquirir arma?","titulo":"Documentação de aquisição por policial militar — orientação parcial","publico":"policial","produto":"armas","atividade":"aquisicao","texto":"Identifique arma permitida ou restrita: a competência muda. O acervo não contém a lista documental integral do requerimento e dos anexos deste caso. Informe instituição/UF, ativa ou inatividade e modalidade de aquisição e confira o procedimento do órgão de vinculação. A referência abaixo não comprova uma lista documental completa.","referencias":[{"norma":"Portaria nº 167 COLOG/C Ex, de 22 de janeiro de 2024","referencia":"Normas, art. 2º, § 1º, incisos I e II"}],"fontes_complementares":[]},{"pergunta_modelo":"Como transferir uma arma do SINARM para o SIGMA?","titulo":"Migração SINARM para SIGMA","publico":"todos","produto":"armas","atividade":"registro","texto":"Identifique a origem: Sinarm-Defesa Pessoal e Sinarm-CAC têm serviços distintos. Para Defesa Pessoal → Sigma, a PF orienta requerimento à delegacia da circunscrição com identificação militar, vínculo institucional, CRAF e documento de compra/venda ou doação quando aplicável. Depois, cumpra o cadastro militar. Para PM/CBM/GSI, o órgão de vinculação encaminha o processo à RM. Migração e transferência de propriedade são distintas.","referencias":[{"norma":"Portaria nº 167 COLOG/C Ex, de 22 de janeiro de 2024","referencia":"Normas, art. 6º, caput e inciso I"},{"norma":"Portaria nº 167 COLOG/C Ex, de 22 de janeiro de 2024","referencia":"Normas, art. 7º, caput e § 1º"}],"fontes_complementares":[{"titulo":"PF — Migração para Sigma","url":"https://www.gov.br/pt-br/servicos/obter-migracao-de-arma-de-fogo-do-sinarm-defesa-pessoal-para-o-sigma","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"Como transferir uma arma do SIGMA para o SINARM?","titulo":"Migração SIGMA para SINARM","publico":"todos","produto":"armas","atividade":"registro","texto":"Identifique finalidade e destino. Para Sinarm-Defesa Pessoal, a PF orienta requerimento de registro sem autorização prévia, com autorização de migração do sistema de origem e documentação exigida. O rito muda se já existir cadastro. A exclusão das Forças Armadas exige providenciar transferência no regime militar. Para acervo CAC, use o serviço específico de transferência para Sinarm-CAC.","referencias":[{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 31"}],"fontes_complementares":[{"titulo":"PF — Migração para Sinarm-Defesa Pessoal","url":"https://www.gov.br/pt-br/servicos/obter-migracao-de-arma-de-fogo-para-o-sinarm-defesa-pessoal","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"O que é o SICOEX?","titulo":"Sistema de Controle de Explosivos","publico":"empresa","produto":"explosivos","atividade":"todos","texto":"SICOEX é o Sistema de Controle de Explosivos no SisFPC. Serve ao controle, informações, autorizações de aquisição e de detonação e relatórios. Empresas abrangidas registram entradas e saídas com origem/destino, especificações e identificação individual seriada.","referencias":[{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 4º"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 5º e §§ 1º e 2º"}],"fontes_complementares":[]},{"pergunta_modelo":"Como adquirir explosivos pelo SICOEX?","titulo":"Aquisição de explosivos pelo SICOEX","publico":"empresa","produto":"explosivos","atividade":"aquisicao","texto":"A pessoa registrada solicita autorização com adquirente, produtos, fornecedor e comprovante da taxa. Exige armazenagem registrada, própria ou terceirizada, ressalvado emprego imediato. Observe apostilamento e contrato exigidos. Pessoas isentas de registro têm rito específico perante a OM do SisFPC.","referencias":[{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 62 e §§ 1º e 2º"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 63 e §§ 1º a 4º"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 64 e §§ 1º e 2º"}],"fontes_complementares":[]},{"pergunta_modelo":"Como funciona o tráfego de explosivos?","titulo":"Tráfego de explosivos","publico":"empresa","produto":"explosivos","atividade":"transporte","texto":"A GT acompanha os explosivos em todos os percursos com Termo de Transferência de Posse assinado e documento fiscal. Exige escolta armada, ressalvada UMB transportando exclusivamente emulsão base. Retorno de sobra, não execução ou devolução têm rito próprio de guia. Confira as demais condições de segurança.","referencias":[{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 67"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 69 e parágrafo único"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 28"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 28, parágrafo único"},{"norma":"Portaria nº 147 COLOG, de 21 de novembro de 2019","referencia":"Art. 70"}],"fontes_complementares":[]},{"pergunta_modelo":"Quais marcações uma arma importada precisa ter?","titulo":"Marcações de armas importadas","publico":"todos","produto":"armas","atividade":"importacao","texto":"Confira fabricante, país, calibre, série nas peças exigidas, ano quando não integrar a série e modelo. Importação por empresa também exige identificação do importador. Complementar marcações no Brasil depende de autorização e marcações mínimas de fábrica. Importação direta por pessoa física e admissão temporária têm regras próprias.","referencias":[{"norma":"Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021","referencia":"Normas, art. 4º, caput e incisos I a VI"},{"norma":"Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021","referencia":"Normas, art. 10, caput e § 1º"},{"norma":"Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021","referencia":"Normas, art. 11, caput"},{"norma":"Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021","referencia":"Normas, art. 12, caput"}],"fontes_complementares":[]},{"pergunta_modelo":"Quando uma arma pode ser remarcada?","titulo":"Autorização para remarcação","publico":"todos","produto":"armas","atividade":"todos","texto":"Identificação suprimida ou adulterada pode ser remarcada mediante autorização do COLOG/DFPC e laudo capaz de recuperar integralmente a marcação original. A execução cabe ao fabricante nacional ou empresa/profissional especializado para importadas, mediante autorização. Deve reproduzir a marcação original nas condições do dispositivo.","referencias":[{"norma":"Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021","referencia":"Normas, art. 14, caput e §§ 1º a 3º"}],"fontes_complementares":[]},{"pergunta_modelo":"Como funciona a importação de PCE?","titulo":"Importação de PCE","publico":"todos","produto":"todos","atividade":"importacao","texto":"O processo compreende registro da LPCO, análise e deferimento, registro da DUIMP, inspeção quando cabível e deferimento da DUIMP. Obtenha LPCO antes do embarque. Produto, importador e finalidade determinam condições específicas; importações diretas pelas Forças Armadas são ressalvadas.","referencias":[{"norma":"Portaria C Ex nº 2.566, de 8 de outubro de 2025","referencia":"Normas, art. 1º"},{"norma":"Portaria C Ex nº 2.566, de 8 de outubro de 2025","referencia":"Normas, art. 3º — texto completo"},{"norma":"Portaria C Ex nº 2.566, de 8 de outubro de 2025","referencia":"Normas, art. 12 — texto completo"}],"fontes_complementares":[]},{"pergunta_modelo":"O que são LPCO e DUIMP na importação de PCE?","titulo":"LPCO e DUIMP","publico":"todos","produto":"todos","atividade":"importacao","texto":"LPCO significa Licenças, Permissões, Certificados e Outros Documentos; DUIMP é a Declaração Única de Importação. LPCO integra licenciamento; DUIMP recebe a conferência do Exército com exame documental e inspeção nas hipóteses previstas. São etapas distintas no Portal Único.","referencias":[{"norma":"Portaria C Ex nº 2.566, de 8 de outubro de 2025","referencia":"Normas, art. 2º — texto completo"},{"norma":"Portaria C Ex nº 2.566, de 8 de outubro de 2025","referencia":"Normas, art. 3º — texto completo"}],"fontes_complementares":[]},{"pergunta_modelo":"Empresa de segurança privada pode adquirir munição calibre 12?","titulo":"Calibre 12 na segurança privada","publico":"empresa","produto":"municoes","atividade":"aquisicao","texto":"Depende do tipo de munição. A norma contempla calibre 12 com agente irritante ou projéteis de borracha/plástico e os casos de balins e cartuchos para lançamento de menor potencial ofensivo. Exige registro na PF e anuência/autorização aplicáveis. Não autoriza toda munição calibre 12: informe tipo e finalidade.","referencias":[{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, caput"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, § 1º"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, inciso VI"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, inciso VII"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 2º"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 3º"}],"fontes_complementares":[]},{"pergunta_modelo":"Quais PCE de menor potencial ofensivo podem ser adquiridos por empresa de segurança privada?","titulo":"Menor potencial ofensivo na segurança privada","publico":"empresa","produto":"menos_letais","atividade":"aquisicao","texto":"A lista contempla espargidores CS/OC nas especificações, dardos energizados, determinadas armas de pressão, granadas irritantes/fumígenas, lançadores e munições calibre 12 indicados, máscaras e filtros. Leia as especificações nos incisos. Exige registro na PF e anuência/autorização. Colete balístico é relacionado separadamente.","referencias":[{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, caput"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, § 1º"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, § 2º"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, incisos I a IX"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 1º, inciso X"},{"norma":"Portaria COLOG/C Ex nº 291, de 10 de agosto de 2026","referencia":"Art. 3º"}],"fontes_complementares":[]},{"pergunta_modelo":"Qual o nível de risco de atividade econômica com PCE?","titulo":"Risco econômico e CNAE","publico":"empresa","produto":"todos","atividade":"todos","texto":"A Portaria 800/2020 aprova tabela por atividade e estabelece que atividades com PCE não sejam classificadas no nível I. Para o nível específico, identifique CNAE e atividade efetiva e consulte a linha do anexo. CNAE isolado não comprova dispensa de registro ou autorização. O acervo não contém todas as linhas para classificar qualquer CNAE.","referencias":[{"norma":"Portaria nº 800, de 14 de agosto de 2020","referencia":"Art. 1º"},{"norma":"Portaria nº 800, de 14 de agosto de 2020","referencia":"Art. 2º"},{"norma":"Portaria nº 56 COLOG, de 5 de junho de 2017","referencia":"Art. 7º e §§ 1º e 2º"}],"fontes_complementares":[]},{"pergunta_modelo":"Como funciona a classificação por CNAE para atividade com PCE?","titulo":"Risco econômico e CNAE","publico":"empresa","produto":"todos","atividade":"todos","texto":"A Portaria 800/2020 aprova tabela por atividade e estabelece que atividades com PCE não sejam classificadas no nível I. Para o nível específico, identifique CNAE e atividade efetiva e consulte a linha do anexo. CNAE isolado não comprova dispensa de registro ou autorização. O acervo não contém todas as linhas para classificar qualquer CNAE.","referencias":[{"norma":"Portaria nº 800, de 14 de agosto de 2020","referencia":"Art. 1º"},{"norma":"Portaria nº 800, de 14 de agosto de 2020","referencia":"Art. 2º"},{"norma":"Portaria nº 56 COLOG, de 5 de junho de 2017","referencia":"Art. 7º e §§ 1º e 2º"}],"fontes_complementares":[]},{"pergunta_modelo":"O que é o SisFPC?","titulo":"SisFPC e fiscalização","publico":"todos","produto":"todos","atividade":"fiscalizacao","texto":"SisFPC é o Sistema de Fiscalização de Produtos Controlados. O Exército regulamenta, autoriza e fiscaliza no âmbito de sua competência, com cooperação dos órgãos do regulamento. Para armas e CAC, identifique o serviço: a PF mantém serviços no Sinarm-Defesa Pessoal e Sinarm-CAC. Não generalize competências a partir de um trecho antigo.","referencias":[{"norma":"Decreto nº 10.030, de 30 de setembro de 2019","referencia":"Anexo I, art. 11, caput e incisos I a V"},{"norma":"Decreto nº 10.030, de 30 de setembro de 2019","referencia":"Anexo I, art. 13, caput e incisos I a VI"}],"fontes_complementares":[{"titulo":"PF — Serviços e competências atuais","url":"https://www.gov.br/pf/pt-br/assuntos/armas","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"Quem fiscaliza produtos controlados pelo Exército?","titulo":"SisFPC e fiscalização","publico":"todos","produto":"todos","atividade":"fiscalizacao","texto":"SisFPC é o Sistema de Fiscalização de Produtos Controlados. O Exército regulamenta, autoriza e fiscaliza no âmbito de sua competência, com cooperação dos órgãos do regulamento. Para armas e CAC, identifique o serviço: a PF mantém serviços no Sinarm-Defesa Pessoal e Sinarm-CAC. Não generalize competências a partir de um trecho antigo.","referencias":[{"norma":"Decreto nº 10.030, de 30 de setembro de 2019","referencia":"Anexo I, art. 11, caput e incisos I a V"},{"norma":"Decreto nº 10.030, de 30 de setembro de 2019","referencia":"Anexo I, art. 13, caput e incisos I a VI"}],"fontes_complementares":[{"titulo":"PF — Serviços e competências atuais","url":"https://www.gov.br/pf/pt-br/assuntos/armas","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"O que é TFPC e quem precisa pagar?","titulo":"Taxa de Fiscalização de Produtos Controlados","publico":"todos","produto":"todos","atividade":"todos","texto":"TFPC é a Taxa de Fiscalização dos Produtos Controlados pelo Exército. O fato gerador é o exercício regular do poder de polícia; sujeitos passivos são pessoas físicas e jurídicas que exercem atividades com PCE. A cobrança depende da hipótese e valor no anexo da Lei 10.834/2003, com suas isenções. O pagamento é requisito prévio ao processamento da pretensão.","referencias":[{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 1º"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 1º, parágrafo único"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 2º, caput"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 2º, § 1º"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 3º"}],"fontes_complementares":[]},{"pergunta_modelo":"Quem é isento da TFPC?","titulo":"Isenções da TFPC","publico":"todos","produto":"todos","atividade":"todos","texto":"A lei prevê entes públicos e autarquias/fundações; ensino e pesquisa oficialmente reconhecidos; uso apenas como fertilizante; uso medicinal por hospitais/clínicas; purificação de água; farmácias/drogarias nas condições e limite legal; e comércio de brinquedos que somente transacione as armas de pressão por mola permitidas indicadas. Leia todas as condições nos incisos. Isenção da TFPC não significa dispensa de registro, autorização ou toda outra taxa.","referencias":[{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, caput"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso I"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso II"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso III"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso IV"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso V"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso VI"},{"norma":"Lei nº 10.834, de 29 de dezembro de 2003","referencia":"Art. 4º, inciso VII"}],"fontes_complementares":[]},{"pergunta_modelo":"Atirador pode comprar equipamento de recarga?","titulo":"Equipamentos de recarga para atirador","publico":"cac","produto":"outros","atividade":"aquisicao","texto":"Pode adquirir mediante autorização e apostilamento para a atividade autorizada. A ITA 31/2025 prevê um equipamento por calibre de arma apostilada, matrizes correspondentes e equipamento não pneumático para recarga artesanal. Sem armas apostiladas não cabe nova aquisição; há transição para equipamentos anteriores. A PF informa que máquinas de recarga e outros insumos permanecem sob controle do Exército.","referencias":[{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Arts. 1º e 2º — autorização e apostilamento"},{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Art. 3º e §§ 1º e 2º"},{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Art. 4º"},{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Art. 5º e §§ 1º e 2º"}],"fontes_complementares":[{"titulo":"PF — Serviços e competências atuais","url":"https://www.gov.br/pf/pt-br/assuntos/armas","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"Quantos equipamentos de recarga um atirador pode ter?","titulo":"Equipamentos de recarga para atirador","publico":"cac","produto":"outros","atividade":"aquisicao","texto":"Pode adquirir mediante autorização e apostilamento para a atividade autorizada. A ITA 31/2025 prevê um equipamento por calibre de arma apostilada, matrizes correspondentes e equipamento não pneumático para recarga artesanal. Sem armas apostiladas não cabe nova aquisição; há transição para equipamentos anteriores. A PF informa que máquinas de recarga e outros insumos permanecem sob controle do Exército.","referencias":[{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Arts. 1º e 2º — autorização e apostilamento"},{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Art. 3º e §§ 1º e 2º"},{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Art. 4º"},{"norma":"ITA nº 31, de 4 de setembro de 2025","referencia":"Art. 5º e §§ 1º e 2º"}],"fontes_complementares":[{"titulo":"PF — Serviços e competências atuais","url":"https://www.gov.br/pf/pt-br/assuntos/armas","verificado_em":"2026-10-08"}]},{"pergunta_modelo":"Quais regras existem para colete balístico?","titulo":"Coletes: aquisição e destinação","publico":"todos","produto":"blindagem","atividade":"todos","texto":"Depende do nível, adquirente e finalidade. A norma admite aquisição por pessoa física até IIIA/HG2. Aquisições institucionais têm transição em 2026: nas condições citadas, até 31/12/2026 aplica-se comunicação para os coletes indicados; não antecipe exigência futura. EPBI expirado, irrecuperável ou inservível deve ser destruído, sem reutilização. Informe nível e adquirente.","referencias":[{"norma":"Portaria COLOG/C Ex nº 289, de 22 de maio de 2026","referencia":"Normas, art. 53, caput"},{"norma":"Portaria COLOG/C Ex nº 289, de 22 de maio de 2026","referencia":"Normas, art. 48, § 4º — regra transitória 2026"},{"norma":"Portaria COLOG/C Ex nº 289, de 22 de maio de 2026","referencia":"Normas, art. 54, caput e § 1º"}],"fontes_complementares":[]},{"pergunta_modelo":"Como funciona o SICOVAB?","titulo":"Controle de veículos e proteções balísticas","publico":"empresa","produto":"blindagem","atividade":"todos","texto":"SICOVAB gerencia atividades com blindagens e veículos automotores blindados. Pessoas jurídicas devem ter registro. Blindagem de veículo, aplicação em viatura de OSOP e fabricação de carro-forte dependem de autorização prévia pelo sistema. Comércio e execução têm condições próprias; cadastrar veículo não autoriza toda atividade.","referencias":[{"norma":"Portaria COLOG/C Ex nº 290, de 4 de maio de 2026","referencia":"Normas, arts. 1º a 4º"},{"norma":"Portaria COLOG/C Ex nº 290, de 4 de maio de 2026","referencia":"Normas, art. 6º, caput e incisos I a III"},{"norma":"Portaria COLOG/C Ex nº 290, de 4 de maio de 2026","referencia":"Normas, art. 31, caput e §§ 1º e 2º"},{"norma":"Portaria COLOG/C Ex nº 290, de 4 de maio de 2026","referencia":"Normas, art. 39 e parágrafo único"}],"fontes_complementares":[]},{"pergunta_modelo":"CAC pode portar arma carregada fora do trajeto autorizado?","titulo":"Limites do porte de trânsito de CAC","publico":"cac","produto":"armas","atividade":"transporte","texto":"Não com base na condição de CAC ou na GT. A guia ampara transporte desmuniciado com munição em recipiente próprio, finalidade, período e itinerário definidos. Eventual porte por outro fundamento exige autorização própria e não decorre da guia.","referencias":[{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 33, caput e §§ 1º a 3º"}],"fontes_complementares":[]},{"pergunta_modelo":"Qual a diferença entre porte e transporte de arma?","titulo":"Porte e transporte","publico":"todos","produto":"armas","atividade":"transporte","texto":"Porte e transporte têm fundamentos e documentos distintos. No trânsito de CAC, a GT ampara deslocamento desmuniciado dentro da finalidade, prazo e trajeto; não autoriza porte de defesa pessoal. Militar sem porte também necessita da GT correspondente. Identifique categoria, registro, finalidade e autorização para avaliar o caso.","referencias":[{"norma":"Decreto nº 11.615, de 21 de julho de 2023","referencia":"Art. 33, caput e §§ 1º a 3º"},{"norma":"Portaria nº 164 COLOG/C Ex, de dezembro de 2023","referencia":"Normas, art. 29 e §§ 1º e 2º"}],"fontes_complementares":[]}]$dados$::jsonb) loop
  select jsonb_agg(d.id::text order by r.ord) into refs
  from jsonb_array_elements(g->'referencias') with ordinality r(value,ord)
  join normas n on n.titulo=r.value->>'norma'
  join dispositivos d on d.norma_id=n.id and d.referencia=r.value->>'referencia';
  if jsonb_array_length(coalesce(refs,'[]'))<>jsonb_array_length(g->'referencias') then
   raise exception 'Referências incompletas: %',g->>'pergunta_modelo';
  end if;
  select id into alvo from orientacoes_empresariais
   where chave_pergunta_pce(pergunta_modelo)=chave_pergunta_pce(g->>'pergunta_modelo') limit 1;
  if alvo is null then
   insert into orientacoes_empresariais(titulo,pergunta_modelo,produto,atividade,publico,secoes,estado)
   values(g->>'titulo',g->>'pergunta_modelo',g->>'produto',g->>'atividade',g->>'publico',
    jsonb_build_array(jsonb_build_object('titulo','Resposta e condições','texto',g->>'texto',
     'dispositivo_ids',refs,'fontes_complementares',g->'fontes_complementares')),'publicada');
  else
   update orientacoes_empresariais set titulo=g->>'titulo',produto=g->>'produto',
    atividade=g->>'atividade',publico=g->>'publico',
    secoes=jsonb_build_array(jsonb_build_object('titulo','Resposta e condições','texto',g->>'texto',
     'dispositivo_ids',refs,'fontes_complementares',g->'fontes_complementares')),estado='publicada'
    where id=alvo;
  end if;
 end loop;
end $seed$;

create or replace function public.consultar_publico_pce(
 p_pergunta text,p_produto text default 'todos',p_atividade text default 'todos',
 p_publico text default 'automatico',p_data date default current_date,p_limite integer default 10
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare q text:=chave_pergunta_pce(p_pergunta); resultado jsonb; guia orientacoes_empresariais;
 refs text[]; fontes jsonb; norma_ids uuid[]; cit text[]; ano_citado integer; itens jsonb;
begin
 resultado:=jsonb_build_object('fontes','[]'::jsonb,'orientacoes','[]'::jsonb,
 'data_referencia',p_data,'versao','publicos-v1-2026-10-08','fontes_excluidas',0);
 if p_data is distinct from (now() at time zone 'America/Sao_Paulo')::date then
  return resultado||jsonb_build_object('aviso_referencia','Esta consulta trabalha com a data atual. Redações históricas e futuras não serão tratadas como fundamento atual.');
 end if;
 if q in (chave_pergunta_pce('Uma norma revogada ainda pode ser usada como fundamento?'),
          chave_pergunta_pce('Se uma portaria foi alterada, qual redação vale hoje?')) then
  return resultado||jsonb_build_object('metodologia',jsonb_build_object(
   'titulo','Vigência e redação aplicável',
   'texto',case when q like 'uma norma%' then
    'Dispositivo revogado não fundamenta uma obrigação atual. Pode ser relevante para analisar fatos do período em que vigorava, respeitados os efeitos temporais. Esta aplicação separa histórico e fundamento atual e não presume que a revogação de parte da norma revogou o restante.'
    else 'Use a redação aplicável à data do caso, incorporando alterações já eficazes e preservando os dispositivos não alterados. Uma redação intermediária substituída ou uma exigência com eficácia futura não deve ser apresentada como regra atual. Quando faltar consolidação conferida, a aplicação deve indicar a lacuna.' end,
   'fonte_oficial','https://www.planalto.gov.br/ccivil_03/decreto-lei/del4657compilado.htm',
   'referencia','LINDB, art. 2º — regra geral de vigência; análise temporal depende do caso'));
 end if;
 -- Artigo exato tem precedência. Corpo principal e normas aprovadas exigem escolha.
 resultado:=public.consultar_referencia_pce(p_pergunta,p_data);
 if resultado is not null then return resultado; end if;
 resultado:=jsonb_build_object('fontes','[]'::jsonb,'orientacoes','[]'::jsonb,
 'data_referencia',p_data,'versao','publicos-v1-2026-10-08','fontes_excluidas',0);
 if q ~ '\m(decreto|portaria|lei|ita)\M' and q ~ 'vigente|vigencia|revog|alter|mudou|ainda.*usad' then
  cit:=regexp_match(lower(p_pergunta),'\m(decreto|portaria(?:[ ]+conjunta)?|lei|ita)[ ]+(?:n[º°o.]*[ ]*)?([0-9][0-9.]*)');
  ano_citado:=nullif(substring(lower(p_pergunta) from '(?:/|\mde[ ]+)(19[0-9]{2}|20[0-9]{2})\M'),'')::integer;
  select array_agg(n.id) into norma_ids from normas n where
   (chave_pergunta_pce(n.titulo)=q or position(chave_pergunta_pce(n.titulo) in q)>0)
   or (cit is not null and
    lower(n.tipo) like split_part(cit[1],' ',1)||'%' and
    (cit[1]<>'portaria conjunta' or lower(n.titulo) like '%conjunta%') and
    ltrim(regexp_replace(substring(n.numero from '^[0-9.]+'),'[^0-9]','','g'),'0')=
    ltrim(regexp_replace(cit[2],'[^0-9]','','g'),'0') and (ano_citado is null or n.ano=ano_citado));
  select coalesce(jsonb_agg(jsonb_build_object(
   'norma_id',n.id,'titulo',n.titulo,'status',n.status,'observacao',n.observacao_vigencia,
   'ultima_verificacao',n.ultima_verificacao,'fonte_oficial',n.fonte_oficial,
   'eventos',coalesce((select jsonb_agg(jsonb_build_object(
    'norma_base',e.norma_base,'norma_alteradora',e.norma_alteradora,
    'dispositivo',e.dispositivo_base,'tipo',e.tipo_alteracao,
    'data',e.vigencia_inicio,'resumo',e.texto_novo,'observacoes',e.observacoes
   ) order by e.vigencia_inicio) from v_linha_tempo_normativa e
    where e.conferido and (e.norma_base_id=n.id or e.norma_alteradora_id=n.id)),'[]'::jsonb),
   'mapa',coalesce((select jsonb_agg(jsonb_build_object(
    'dispositivo',v.dispositivo,'status',v.status_dispositivo,
    'data',v.data_efeito,'responsavel',v.norma_responsavel,'observacoes',v.observacoes
   ) order by v.dispositivo) from v_mapa_vigencia_normativa v
   where v.conferido and v.norma_id=n.id),'[]'::jsonb)
  ) order by n.titulo),'[]'::jsonb) into itens from normas n where n.id=any(norma_ids);
  return resultado||jsonb_build_object('historico_normativo',itens,
   'aviso_referencia',case when jsonb_array_length(itens)=0 then
    'Não localizei a norma exata. Informe tipo, número, ano e órgão. A ausência não comprova revogação.'
    when jsonb_array_length(itens)>1 then
    'Há mais de uma norma compatível. Identifique o órgão e a norma antes de concluir sobre a vigência.'
    else 'Situação e alterações cadastradas, separadas dos fundamentos atuais. A lista pode não abranger todas as alterações; redações intermediárias são histórico. Confira o dispositivo e o texto consolidado antes de aplicar.' end);
 end if;
 select o.* into guia from orientacoes_empresariais o
 where o.estado='publicada' and chave_pergunta_pce(o.pergunta_modelo)=q
 order by o.updated_at desc limit 1;
 if guia.id is not null then
  if p_publico not in ('automatico','todos') and guia.publico not in ('todos',p_publico)
   or p_produto<>'todos' and guia.produto not in ('todos',p_produto)
   or p_atividade<>'todos' and guia.atividade not in ('todos',p_atividade) then
   return resultado||jsonb_build_object('aviso_referencia','O público, produto ou atividade selecionado contradiz a orientação da pergunta. Ajuste os filtros.');
  end if;
  select array_agg(distinct ref) into refs from jsonb_array_elements(guia.secoes) s,
   jsonb_array_elements_text(s->'dispositivo_ids') ref;
  fontes:=fontes_dispositivos_pce(refs,p_data);
  if jsonb_array_length(fontes)<>coalesce(cardinality(refs),0) then
   return resultado||jsonb_build_object('aviso_referencia','Há fundamento ausente, não conferido ou sem vigência atual. A orientação foi bloqueada até revisão.');
  end if;
  return resultado||jsonb_build_object('fontes',fontes,'orientacoes',jsonb_build_array(to_jsonb(guia)));
 end if;
 -- Texto não revisado não recebe conclusão pronta. Empresa preserva a busca anterior.
 return public.consultar_empresa_pce(p_pergunta,p_produto,p_atividade,
  case when p_publico='empresa' then 'empresa' else 'todos' end,p_data,p_limite);
end $$;
revoke execute on function public.chave_pergunta_pce(text) from public;
revoke execute on function public.fontes_dispositivos_pce(text[],date) from public;
revoke execute on function public.consultar_publico_pce(text,text,text,text,date,integer) from public;
grant execute on function public.chave_pergunta_pce(text) to anon,authenticated;
grant execute on function public.fontes_dispositivos_pce(text[],date) to anon,authenticated;
grant execute on function public.consultar_publico_pce(text,text,text,text,date,integer) to anon,authenticated;
notify pgrst,'reload schema';
